export const PlayerAutonomousTestsTab = ({ player, team, teamPath }) => {
  const { user } = useAuth();
  const { t, isEn, formatDate } = useTranslation();

  const [selectedTest, setSelectedTest] = useState(null);
  const [currentQuestionIdx, setCurrentQuestionIdx] = useState(0);
  const [answers, setAnswers] = useState({});
  const [saving, setSaving] = useState(false);
  const [history, setHistory] = useState({});
  const [loadingHistory, setLoadingHistory] = useState(true);

  // Cargar historial de tests completados por este jugador en tiempo real
  useEffect(() => {
    if (!teamPath || !player?.id) {
      setLoadingHistory(false);
      return;
    }

    const testsColRef = collection(db, `${teamPath}/test_results`);
    const q = query(testsColRef, where('playerId', '==', player.id));
    const unsubscribe = onSnapshot(q, (snap) => {
      const docs = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      docs.sort((a, b) => new Date(b.date || b.timestamp || 0) - new Date(a.date || a.timestamp || 0));

      const historyMap = {};
      docs.forEach(data => {
        if (data.testId && !historyMap[data.testId]) {
          historyMap[data.testId] = data;
        }
      });
      setHistory(historyMap);
      setLoadingHistory(false);
    }, (err) => {
      console.warn('[PlayerAutonomousTestsTab] Error escuchando historial de tests:', err);
      setLoadingHistory(false);
    });

    return () => unsubscribe();
  }, [teamPath, player?.id]);

  const handleStartTest = (test) => {
    setSelectedTest(test);
    setCurrentQuestionIdx(0);
    setAnswers({});
  };

  const handleSelectOption = (value) => {
    if (!selectedTest) return;
    const currentQ = selectedTest.questions[currentQuestionIdx];
    setAnswers(prev => ({ ...prev, [currentQ.id]: value }));

    if (currentQuestionIdx < selectedTest.questions.length - 1) {
      setCurrentQuestionIdx(prev => prev + 1);
    }
  };

  const handlePreviousQuestion = () => {
    if (currentQuestionIdx > 0) {
      setCurrentQuestionIdx(prev => prev - 1);
    }
  };

  const handleSaveTest = async () => {
    if (!selectedTest || !player?.id || !teamPath) return;

    try {
      setSaving(true);
      const totalScore = Object.values(answers).reduce((sum, val) => sum + Number(val || 0), 0);
      const percentage = Math.round((totalScore / selectedTest.maxScore) * 100);
      const now = new Date();
      const dateStr = now.toISOString().slice(0, 10);

      const testPayload = {
        testId: selectedTest.id,
        testName: selectedTest.name,
        shortName: selectedTest.shortName,
        category: selectedTest.category,
        playerId: player.id,
        playerName: player.nombre || player.name || 'Jugador',
        score: totalScore,
        maxScore: selectedTest.maxScore,
        percentage,
        answers,
        date: dateStr,
        timestamp: serverTimestamp(),
        isAutonomous: true,
        source: 'player_portal'
      };

      // 1. Guardar en colección de resultados del equipo
      await addDoc(collection(db, `${teamPath}/test_results`), testPayload);

      // 2. Sincronizar con colección de evaluaciones para que impacte en la ficha y radar
      try {
        const evalDocId = `auto_${selectedTest.id}_${player.id}`;
        await setDoc(doc(db, `${teamPath}/evaluaciones`, evalDocId), {
          playerId: player.id,
          tipo: 'psicologico_auto',
          testId: selectedTest.id,
          nombre: selectedTest.name,
          categoria: selectedTest.category,
          nota: percentage,
          puntuacionTotal: totalScore,
          puntuacionMaxima: selectedTest.maxScore,
          fecha: dateStr,
          fechaActualizacion: serverTimestamp(),
          description: selectedTest.desc,
          isAutonomous: true
        }, { merge: true });
      } catch (evalErr) {
        console.warn('Advertencia guardando en evaluaciones:', evalErr);
      }

      // Actualizar estado local
      setHistory(prev => ({
        ...prev,
        [selectedTest.id]: testPayload
      }));

      showToast(t('test.completedSuccess', { name: selectedTest.shortKey ? t(selectedTest.shortKey, {}, selectedTest.shortName) : selectedTest.shortName, pct: percentage }), 'success');
      setSelectedTest(null);
    } catch (err) {
      console.error('[PlayerAutonomousTestsTab] Error guardando test:', err);
      showToast(t('test.errorSaving'), 'error');
    } finally {
      setSaving(false);
    }
  };

  // ── VISTA DEL CUESTIONARIO EN CURSO ───────────────────────────────────────
  if (selectedTest) {
    const currentQ = selectedTest.questions[currentQuestionIdx];
    const progressPct = Math.round(((currentQuestionIdx + 1) / selectedTest.questions.length) * 100);
    const isCompleted = selectedTest.questions.every(q => answers[q.id] !== undefined);

    return (
      <div className="player-tab-content player-active-test-view">
        <button 
          className="test-back-btn" 
          onClick={() => setSelectedTest(null)}
          type="button"
        >
          <ArrowLeft size={16} /> {t('test.backToCatalog')}
        </button>

        <div className="test-runner-card">
          <div className="test-runner-header">
            <span className="test-runner-cat" style={{ color: selectedTest.color }}>
              {selectedTest.catKey ? t(selectedTest.catKey, {}, selectedTest.category) : selectedTest.category}
            </span>
            <span className="test-runner-step">
              {t('test.questionProgress', { current: currentQuestionIdx + 1, total: selectedTest.questions.length }, `Pregunta ${currentQuestionIdx + 1} de ${selectedTest.questions.length}`)}
            </span>
          </div>

          <div className="test-progress-bar-wrap">
            <div 
              className="test-progress-bar-fill" 
              style={{ width: `${progressPct}%`, backgroundColor: selectedTest.color }}
            />
          </div>

          <div className="test-question-box">
            <span className="test-question-dimension">
              {t('test.dimension')}: {currentQ.dimKey ? t(currentQ.dimKey, {}, currentQ.dimension) : currentQ.dimension}
            </span>
            <h3 className="test-question-text">
              {currentQ.textKey ? t(currentQ.textKey, {}, currentQ.text) : currentQ.text}
            </h3>
          </div>

          <div className="test-options-list">
            {selectedTest.options.map((opt) => {
              const isSelected = answers[currentQ.id] === opt.value;
              return (
                <button
                  key={opt.value}
                  type="button"
                  className={`test-option-btn ${isSelected ? 'selected' : ''}`}
                  onClick={() => handleSelectOption(opt.value)}
                >
                  <span className="opt-indicator">{opt.value}</span>
                  <span className="opt-label">{opt.labelKey ? t(opt.labelKey, {}, opt.label) : opt.label}</span>
                  {isSelected && <CheckCircle2 size={18} className="opt-check" />}
                </button>
              );
            })}
          </div>

          <div className="test-nav-controls">
            <button
              type="button"
              className="btn-prev-question"
              onClick={handlePreviousQuestion}
              disabled={currentQuestionIdx === 0}
            >
              {t('test.previous')}
            </button>

            {isCompleted && (
              <button
                type="button"
                className="btn-finish-test"
                onClick={handleSaveTest}
                disabled={saving}
                style={{ backgroundColor: selectedTest.color }}
              >
                {saving ? t('test.saving') : t('test.finishAndSend')}
              </button>
            )}
          </div>
        </div>
      </div>
    );
  }

  // ── VISTA DEL CATÁLOGO DE TESTS AUTÓNOMOS ──────────────────────────────────
  return (
    <div className="player-tab-content player-tests-catalog-tab">
      <div className="tab-header-box">
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
          <Brain size={22} color="#10B981" />
          <h2 className="tab-title">{t('test.tabTitle')}</h2>
        </div>
        <p className="tab-subtitle">
          {t('test.tabSubtitle')}
        </p>
      </div>

      <div className="autonomous-tests-grid">
        {AUTONOMOUS_TESTS.map((test) => {
          const Icon = test.icon;
          const lastResult = history[test.id];

          return (
            <div key={test.id} className="autonomous-test-card">
              <div className="auto-test-top">
                <div className="auto-test-icon-badge" style={{ background: `${test.color}20`, color: test.color }}>
                  <Icon size={22} />
                </div>
                <div className="auto-test-meta-badge">
                  <span>⏱️ {test.timeMinutes} min</span>
                  <span>{t('test.questionsCount', { count: test.questions.length })}</span>
                </div>
              </div>

              <h3 className="auto-test-title">{test.nameKey ? t(test.nameKey, {}, test.name) : test.name}</h3>
              <p className="auto-test-desc">{test.descKey ? t(test.descKey, {}, test.desc) : test.desc}</p>

              {lastResult ? (
                <div className="auto-test-last-result">
                  <div className="result-score-chip">
                    <Award size={14} color="#10B981" />
                    <span>{t('test.lastResult')}: <strong>{lastResult.percentage}%</strong></span>
                    <span className="result-date">({lastResult.date ? formatDate(lastResult.date) : ''})</span>
                  </div>
                  <button
                    type="button"
                    className="btn-retake-test"
                    onClick={() => handleStartTest(test)}
                  >
                    <RotateCcw size={14} /> {t('test.repeatTest')}
                  </button>
                </div>
              ) : (
                <button
                  type="button"
                  className="btn-start-test"
                  onClick={() => handleStartTest(test)}
                  style={{ borderColor: test.color, color: test.color }}
                >
                  <span>{t('test.startTest')}</span>
                  <ChevronRight size={16} />
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};
